rows=json.loads("[{\"path\":\"src/codex_plugin_scanner/guard/windows_replaceable_file.py\",\"content\":\"\\\"\\\"\\\"Read-only Windows handles for authority files replaced by their owner.\\n\\nSharing permits another authorized handle to replace the file. It grants this\\nhandle no write or delete access. Callers retain their existing path, ownership,\\nprivacy, size, identity, and content checks.\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nimport ctypes\\nimport importlib\\nimport os\\nimport sys\\nfrom ctypes import wintypes\\nfrom functools import lru_cache\\nfrom pathlib import Path\\nfrom typing import Any\\n\\nfrom .windows_paths import _WindowsByHandleFileInformation\\n\\n_GENERIC_READ = 0x80000000\\n_SHARE_READ_WRITE_DELETE = 0x00000007\\n_OPEN_EXISTING = 3\\n_OPEN_REPARSE_POINT = 0x00200000\\n_DIRECTORY_OR_REPARSE = 0x00000010 | 0x00000400\\n_FILE_TYPE_DISK = 1\\n\\n\\n@lru_cache(maxsize=1)\\ndef _file_api() -> Any:\\n    win_dll = getattr(ctypes, \\\"WinDLL\\\", None)\\n    if win_dll is None:\\n        raise OSError(\\\"windows_replaceable_read_unavailable\\\")\\n    api = win_dll(\\\"kernel32\\\", use_last_error=True)\\n    api.CreateFileW.argtypes = [\\n        wintypes.LPCWSTR, wintypes.DWORD, wintypes.DWORD, ctypes.c_void_p,\\n        wintypes.DWORD, wintypes.DWORD, wintypes.HANDLE,\\n    ]\\n    api.CreateFileW.restype = wintypes.HANDLE\\n    api.GetFileInformationByHandle.argtypes = [\\n        wintypes.HANDLE, ctypes.POINTER(_WindowsByHandleFileInformation),\\n    ]\\n    api.GetFileInformationByHandle.restype = wintypes.BOOL\\n    api.GetFileType.argtypes = [wintypes.HANDLE]\\n    api.GetFileType.restype = wintypes.DWORD\\n    api.CloseHandle.argtypes = [wintypes.HANDLE]\\n    api.CloseHandle.restype = wintypes.BOOL\\n    return api\\n\\n\\ndef _windows_error() -> OSError:\\n    get_error = getattr(ctypes, \\\"get_last_error\\\", None)\\n    make_error = getattr(ctypes, \\\"WinError\\\", None)\\n    if get_error is None or make_error is None:\\n        return OSError(\\\"windows_replaceable_read_unavailable\\\")\\n    return make_error(get_error())\\n\\n\\ndef _validated_name(path: Path | str, flags: int) -> str:\\n    if os.name != \\\"nt\\\":\\n        raise OSError(\\\"windows_replaceable_read_unavailable\\\")\\n    allowed = (\\n        os.O_RDONLY | getattr(os, \\\"O_BINARY\\\", 0) | getattr(os, \\\"O_NOINHERIT\\\", 0)\\n        | getattr(os, \\\"O_CLOEXEC\\\", 0) | getattr(os, \\\"O_NOFOLLOW\\\", 0)\\n    )\\n    if type(flags) is not int or flags < 0 or flags & ~allowed:\\n        raise ValueError(\\\"replaceable_descriptor_must_be_read_only\\\")\\n    name = os.fspath(path)\\n    if not isinstance(name, str):\\n        raise TypeError(\\\"replaceable_descriptor_requires_text_path\\\")\\n    if \\\"\\\\0\\\" in name:\\n        raise ValueError(\\\"embedded null character in path\\\")\\n    if len(name.encode(\\\"utf-16-le\\\", errors=\\\"surrogatepass\\\")) // 2 > 32767:\\n        raise ValueError(\\\"path too long for Windows\\\")\\n    return name\\n\\n\\ndef _transfer_descriptor(handle: int) -> int:\\n    msvcrt = importlib.import_module(\\\"msvcrt\\\")\\n    return int(msvcrt.open_osfhandle(\\n        handle, os.O_RDONLY | getattr(os, \\\"O_BINARY\\\", 0) | getattr(os, \\\"O_NOINHERIT\\\", 0),\\n    ))\\n\\n\\ndef _require_disk(api: Any, handle: int) -> None:\\n    set_error = getattr(ctypes, \\\"set_last_error\\\", None)\\n    if set_error is None:\\n        raise OSError(\\\"windows_replaceable_read_unavailable\\\")\\n    set_error(0)\\n    file_type = api.GetFileType(handle)\\n    if file_type == 0:\\n        error = _windows_error()\\n        if getattr(error, \\\"winerror\\\", 0):\\n            raise error\\n    if file_type != _FILE_TYPE_DISK:\\n        raise OSError(\\\"windows_replaceable_read_not_disk\\\")\\n\\n\\ndef _open_descriptor(name: str) -> int:\\n    api = _file_api()\\n    handle = api.CreateFileW(\\n        name, _GENERIC_READ, _SHARE_READ_WRITE_DELETE, None,\\n        _OPEN_EXISTING, _OPEN_REPARSE_POINT, None,\\n    )\\n    if handle in (None, ctypes.c_void_p(-1).value):\\n        raise _windows_error()\\n    try:\\n        information = _WindowsByHandleFileInformation()\\n        if not api.GetFileInformationByHandle(handle, ctypes.byref(information)):\\n            raise _windows_error()\\n        if int(information.dwFileAttributes) & _DIRECTORY_OR_REPARSE:\\n            raise OSError(\\\"windows_replaceable_read_not_regular\\\")\\n        _require_disk(api, handle)\\n        descriptor = _transfer_descriptor(handle)\\n        if descriptor < 0:\\n            raise OSError(\\\"windows_replaceable_read_descriptor_invalid\\\")\\n    except BaseException as error:\\n        try:\\n            if not api.CloseHandle(handle):\\n                raise _windows_error()\\n        except BaseException:\\n            error.add_note(\\\"windows_replaceable_read_close_failed\\\")\\n        raise\\n    # open_osfhandle transferred ownership; the caller closes the CRT descriptor.\\n    return descriptor\\n\\n\\ndef open_replaceable_read_descriptor(path: Path | str, flags: int) -> int:\\n    \\\"\\\"\\\"Match the bounded os.open audit event before the single native open.\\\"\\\"\\\"\\n\\n    name = _validated_name(path, flags)\\n    sys.audit(\\\"open\\\", name, None, flags | getattr(os, \\\"O_NOINHERIT\\\", 0))\\n    return _open_descriptor(name)\\n\\n\\ndef _text_opener(path: str, flags: int) -> int:\\n    # FileIO emitted its original open event before invoking this callback.\\n    return _open_descriptor(_validated_name(path, flags))\\n\\n\\ndef read_replaceable_text(path: Path) -> str:\\n    \\\"\\\"\\\"Keep TextIO's UTF-8, newline, audit, and descriptor ownership behavior.\\\"\\\"\\\"\\n\\n    with open(path, encoding=\\\"utf-8\\\", opener=_text_opener) as handle:\\n        return handle.read()\\n\",\"sha256\":\"d2026abc09b502db0b85403906f96316a1c07908ade4ff8bf18c4843044bad29\",\"bytes\":5222},{\"path\":\"src/codex_plugin_scanner/guard/private_file_io.py\",\"content\":\"\\\"\\\"\\\"Bounded reads for owner-only local authority files.\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nimport os\\nimport stat\\nfrom pathlib import Path\\n\\n\\ndef private_regular_file_is_valid(\\n    path: Path,\\n    *,\\n    require_private_parent: bool = False,\\n) -> bool:\\n    \\\"\\\"\\\"Return whether a path names an owner-only regular file.\\n\\n    Parent validation is optional because some legacy authority files live in a\\n    user-owned directory whose privacy is established elsewhere.\\n    \\\"\\\"\\\"\\n\\n    try:\\n        parent_metadata = path.parent.lstat() if require_private_parent else None\\n        metadata = path.lstat()\\n    except OSError:\\n        return False\\n    if parent_metadata is not None and not _private_directory_metadata_is_valid(parent_metadata):\\n        return False\\n    return _private_file_metadata_is_valid(metadata)\\n\\n\\ndef read_private_regular_bytes(\\n    path: Path,\\n    *,\\n    max_bytes: int,\\n    require_private_parent: bool = False,\\n) -> bytes | None:\\n    \\\"\\\"\\\"Read a private regular file through one bounded, no-follow descriptor.\\\"\\\"\\\"\\n\\n    if type(max_bytes) is not int or max_bytes < 1:\\n        raise ValueError(\\\"max_bytes must be a positive integer\\\")\\n    try:\\n        parent_before = path.parent.lstat() if require_private_parent else None\\n        path_before = path.lstat()\\n    except OSError:\\n        return None\\n    if parent_before is not None and not _private_directory_metadata_is_valid(parent_before):\\n        return None\\n    if not _private_file_metadata_is_valid(path_before):\\n        return None\\n\\n    flags = os.O_RDONLY | getattr(os, \\\"O_CLOEXEC\\\", 0) | getattr(os, \\\"O_NOFOLLOW\\\", 0)\\n    try:\\n        if os.name == \\\"nt\\\":\\n            from .windows_replaceable_file import open_replaceable_read_descriptor\\n\\n            descriptor = open_replaceable_read_descriptor(path, flags)\\n        else:\\n            descriptor = os.open(path, flags)\\n    except OSError:\\n        return None\\n    try:\\n        opened = os.fstat(descriptor)\\n        if not _private_file_metadata_is_valid(opened) or not _same_file(\\n            path_before,\\n            opened,\\n        ):\\n            return None\\n        if opened.st_size > max_bytes:\\n            return None\\n        chunks: list[bytes] = []\\n        consumed = 0\\n        while consumed < max_bytes:\\n            chunk = os.read(\\n                descriptor,\\n                min(64 * 1024, max_bytes - consumed),\\n            )\\n            if not chunk:\\n                break\\n            chunks.append(chunk)\\n            consumed += len(chunk)\\n        closed_state = os.fstat(descriptor)\\n        if not _stable_file_metadata(opened, closed_state):\\n            return None\\n    finally:\\n        os.close(descriptor)\\n\\n    if require_private_parent:\\n        try:\\n            parent_after = path.parent.lstat()\\n        except OSError:\\n            return None\\n        if parent_before is None or not _stable_directory_metadata(\\n            parent_before,\\n            parent_after,\\n        ):\\n            return None\\n    return b\\\"\\\".join(chunks)\\n\\n\\ndef read_private_regular_text(\\n    path: Path,\\n    *,\\n    max_bytes: int,\\n    require_private_parent: bool = False,\\n) -> str | None:\\n    \\\"\\\"\\\"Read bounded UTF-8 text from a private regular file.\\\"\\\"\\\"\\n\\n    payload = read_private_regular_bytes(\\n        path,\\n        max_bytes=max_bytes,\\n        require_private_parent=require_private_parent,\\n    )\\n    if payload is None:\\n        return None\\n    try:\\n        return payload.decode(\\\"utf-8\\\").strip()\\n    except UnicodeDecodeError:\\n        return None\\n\\n\\ndef _private_file_metadata_is_valid(metadata: os.stat_result) -> bool:\\n    if stat.S_ISLNK(metadata.st_mode) or not stat.S_ISREG(metadata.st_mode):\\n        return False\\n    if os.name == \\\"nt\\\":\\n        return True\\n    return metadata.st_uid == os.getuid() and not stat.S_IMODE(metadata.st_mode) & 0o077\\n\\n\\ndef _private_directory_metadata_is_valid(metadata: os.stat_result) -> bool:\\n    if not stat.S_ISDIR(metadata.st_mode):\\n        return False\\n    if os.name == \\\"nt\\\":\\n        return True\\n    return metadata.st_uid == os.getuid() and not stat.S_IMODE(metadata.st_mode) & 0o077\\n\\n\\ndef _same_file(left: os.stat_result, right: os.stat_result) -> bool:\\n    return left.st_dev == right.st_dev and left.st_ino == right.st_ino\\n\\n\\ndef _stable_file_metadata(\\n    before: os.stat_result,\\n    after: os.stat_result,\\n) -> bool:\\n    return (\\n        _same_file(before, after)\\n        and before.st_mode == after.st_mode\\n        and before.st_size == after.st_size\\n        and before.st_mtime_ns == after.st_mtime_ns\\n        and before.st_ctime_ns == after.st_ctime_ns\\n    )\\n\\n\\ndef _stable_directory_metadata(\\n    before: os.stat_result,\\n    after: os.stat_result,\\n) -> bool:\\n    \\\"\\\"\\\"Confirm the parent directory was not replaced or made non-private.\\n\\n    Sibling writes update directory mtime/ctime, so those timestamps are not\\n    part of the identity check.\\n    \\\"\\\"\\\"\\n\\n    return _private_directory_metadata_is_valid(after) and _same_file(before, after) and before.st_mode == after.st_mode\\n\\n\\n__all__ = [\\n    \\\"private_regular_file_is_valid\\\",\\n    \\\"read_private_regular_bytes\\\",\\n    \\\"read_private_regular_text\\\",\\n]\\n\",\"sha256\":\"222fa0aa777f7826cef9b1f683fc9a3e05dd5cb70ac5e77d9eda82e100b6fbda\",\"bytes\":5059},{\"path\":\"src/codex_plugin_scanner/guard/adapters/codex_daemon_hook_auth.py\",\"content\":\"\\\"\\\"\\\"Authenticated transport primitives for the Codex daemon hook bridge.\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nimport hashlib\\nimport hmac\\nimport http.client\\nimport json\\nimport os\\nimport secrets\\nimport stat\\nimport time\\nfrom collections.abc import Mapping\\nfrom pathlib import Path\\nfrom urllib.parse import urlparse\\n\\n_LOOPBACK_HOSTS = frozenset({\\\"127.0.0.1\\\", \\\"localhost\\\", \\\"::1\\\"})\\n_DISCOVERY_PROTOCOL_VERSION = 1\\n_DISCOVERY_CHALLENGE_TTL_SECONDS = 5\\n_MAX_DAEMON_RESPONSE_BYTES = 1_000_000\\n_MINIMUM_OPERATION_SECONDS = 0.01\\n\\n\\nclass _DaemonResponseError(ValueError):\\n    def __init__(self, status: int, detail: str, *, authenticated: bool) -> None:\\n        super().__init__(f\\\"daemon returned HTTP {status}\\\")\\n        self.status = status\\n        self.detail = detail\\n        self.authenticated = authenticated\\n\\n\\ndef _assert_loopback_http_url(url: str) -> None:\\n    parsed = urlparse(url)\\n    if parsed.scheme != \\\"http\\\":\\n        raise ValueError(f\\\"daemon URL must use http, not {parsed.scheme!r}\\\")\\n    if parsed.username is not None or parsed.password is not None:\\n        raise ValueError(\\\"daemon URL must not contain credentials\\\")\\n    host = (parsed.hostname or \\\"\\\").lower()\\n    if host not in _LOOPBACK_HOSTS:\\n        raise ValueError(f\\\"daemon URL must target loopback, not {host!r}\\\")\\n    if parsed.port is None:\\n        raise ValueError(\\\"daemon URL must include an explicit port\\\")\\n\\n\\ndef _json_object(text: str) -> dict[str, object] | None:\\n    try:\\n        payload = json.loads(text)\\n    except json.JSONDecodeError:\\n        return None\\n    return payload if isinstance(payload, dict) else None\\n\\n\\ndef _private_file_text(path: Path, *, label: str) -> str:\\n    try:\\n        parent_metadata = path.parent.lstat()\\n        metadata = path.lstat()\\n    except OSError as error:\\n        raise ValueError(f\\\"{label} is unavailable\\\") from error\\n    if not stat.S_ISDIR(parent_metadata.st_mode):\\n        raise ValueError(\\\"Guard home is not a directory\\\")\\n    if stat.S_ISLNK(metadata.st_mode) or not stat.S_ISREG(metadata.st_mode):\\n        raise ValueError(f\\\"{label} must be a regular file\\\")\\n    if os.name != \\\"nt\\\":\\n        if parent_metadata.st_uid != os.getuid() or metadata.st_uid != os.getuid():\\n            raise ValueError(f\\\"{label} ownership does not match the current user\\\")\\n        if stat.S_IMODE(parent_metadata.st_mode) & 0o077 or stat.S_IMODE(metadata.st_mode) & 0o077:\\n            raise ValueError(f\\\"{label} permissions are not owner-only\\\")\\n    try:\\n        if os.name == \\\"nt\\\":\\n            from ..windows_replaceable_file import read_replaceable_text\\n\\n            return read_replaceable_text(path).strip()\\n        return path.read_text(encoding=\\\"utf-8\\\").strip()\\n    except OSError as error:\\n        raise ValueError(f\\\"{label} is unreadable\\\") from error\\n\\n\\ndef _canonical_discovery_payload(payload: dict[str, object]) -> bytes:\\n    return json.dumps(payload, sort_keys=True, separators=(\\\",\\\", \\\":\\\"), ensure_ascii=True).encode(\\\"utf-8\\\")\\n\\n\\ndef _sign_discovery_payload(discovery_key: str, payload: dict[str, object]) -> str:\\n    try:\\n        key = bytes.fromhex(discovery_key)\\n    except ValueError as error:\\n        raise ValueError(\\\"daemon discovery key is malformed\\\") from error\\n    if len(key) != 32:\\n        raise ValueError(\\\"daemon discovery key is malformed\\\")\\n    return hmac.new(key, _canonical_discovery_payload(payload), hashlib.sha256).hexdigest()\\n\\n\\ndef _authenticated_state(state_path: str | Path) -> tuple[dict[str, object], str]:\\n    path = Path(state_path)\\n    discovery_key = _private_file_text(path.parent / \\\"daemon-discovery-key\\\", label=\\\"daemon discovery key\\\")\\n    try:\\n        payload = json.loads(_private_file_text(path, label=\\\"daemon state\\\"))\\n    except json.JSONDecodeError as error:\\n        raise ValueError(\\\"daemon state is malformed\\\") from error\\n    if not isinstance(payload, dict):\\n        raise ValueError(\\\"daemon state must be a JSON object\\\")\\n    signature = payload.get(\\\"state_signature\\\")\\n    unsigned = {key: value for key, value in payload.items() if key != \\\"state_signature\\\"}\\n    try:\\n        expected_key_id = hashlib.sha256(bytes.fromhex(discovery_key)).hexdigest()\\n    except ValueError as error:\\n        raise ValueError(\\\"daemon discovery key is malformed\\\") from error\\n    if (\\n        not isinstance(signature, str)\\n        or unsigned.get(\\\"discovery_protocol_version\\\") != _DISCOVERY_PROTOCOL_VERSION\\n        or unsigned.get(\\\"discovery_key_id\\\") != expected_key_id\\n        or not secrets.compare_digest(signature, _sign_discovery_payload(discovery_key, unsigned))\\n    ):\\n        raise ValueError(\\\"daemon state authentication failed\\\")\\n    host = unsigned.get(\\\"host\\\")\\n    port = unsigned.get(\\\"port\\\")\\n    pid = unsigned.get(\\\"pid\\\")\\n    state_id = unsigned.get(\\\"state_id\\\")\\n    started_at = unsigned.get(\\\"started_at\\\")\\n    guard_home = unsigned.get(\\\"guard_home\\\")\\n    auth_token_id = unsigned.get(\\\"auth_token_id\\\")\\n    if (\\n        not isinstance(host, str)\\n        or host.lower() not in _LOOPBACK_HOSTS\\n        or not isinstance(port, int)\\n        or not 0 < port <= 65535\\n        or not isinstance(pid, int)\\n        or pid <= 0\\n        or not isinstance(state_id, str)\\n        or not state_id\\n        or not isinstance(started_at, str)\\n        or not started_at\\n        or not isinstance(guard_home, str)\\n        or not isinstance(auth_token_id, str)\\n    ):\\n        raise ValueError(\\\"daemon state identity is incomplete\\\")\\n    try:\\n        expected_guard_home = str(path.parent.resolve())\\n        state_guard_home = str(Path(guard_home).resolve())\\n    except OSError as error:\\n        raise ValueError(\\\"daemon state Guard home is invalid\\\") from error\\n    if state_guard_home != expected_guard_home:\\n        raise ValueError(\\\"daemon state belongs to a different Guard home\\\")\\n    return payload, discovery_key\\n\\n\\ndef _daemon_url(state_path: str | Path) -> str:\\n    payload, _discovery_key = _authenticated_state(state_path)\\n    host = str(payload[\\\"host\\\"])\\n    port = payload.get(\\\"port\\\")\\n    rendered_host = f\\\"[{host}]\\\" if \\\":\\\" in host else host\\n    return f\\\"http://{rendered_host}:{port}\\\"\\n\\n\\ndef _daemon_auth_token(state_path: str | Path, state: Mapping[str, object]) -> str:\\n    path = Path(state_path)\\n    token = _private_file_text(path.parent / \\\"daemon-auth-token\\\", label=\\\"daemon auth token\\\")\\n    expected_token_id = state.get(\\\"auth_token_id\\\")\\n    actual_token_id = hashlib.sha256(token.encode(\\\"utf-8\\\")).hexdigest()\\n    if (\\n        not token\\n        or not isinstance(expected_token_id, str)\\n        or not secrets.compare_digest(actual_token_id, expected_token_id)\\n    ):\\n        raise ValueError(\\\"daemon auth token does not match authenticated state\\\")\\n    return token\\n\\n\\ndef _http_json_response(\\n    response: http.client.HTTPResponse,\\n    *,\\n    label: str,\\n    connection: http.client.HTTPConnection,\\n    deadline: float,\\n    authenticated: bool,\\n) -> dict[str, object]:\\n    body = bytearray()\\n    while len(body) <= _MAX_DAEMON_RESPONSE_BYTES:\\n        remaining = _remaining_seconds(deadline)\\n        if remaining < _MINIMUM_OPERATION_SECONDS:\\n            raise TimeoutError(f\\\"{label} exceeded the hook deadline\\\")\\n        if connection.sock is not None:\\n            connection.sock.settimeout(remaining)\\n        chunk = response.read1(min(64 * 1024, _MAX_DAEMON_RESPONSE_BYTES + 1 - len(body)))\\n        if not chunk:\\n            break\\n        body.extend(chunk)\\n    if len(body) > _MAX_DAEMON_RESPONSE_BYTES:\\n        raise ValueError(f\\\"{label} response is too large\\\")\\n    if response.status != 200:\\n        raise _DaemonResponseError(\\n            response.status,\\n            body.decode(\\\"utf-8\\\", errors=\\\"replace\\\").strip(),\\n            authenticated=authenticated,\\n        )\\n    payload = _json_object(bytes(body).decode(\\\"utf-8\\\", errors=\\\"replace\\\").strip())\\n    if payload is None:\\n        raise ValueError(f\\\"{label} returned malformed JSON\\\")\\n    return payload\\n\\n\\ndef _verify_challenge_response(\\n    response: dict[str, object],\\n    *,\\n    state: Mapping[str, object],\\n    discovery_key: str,\\n    nonce: str,\\n    hook_event: str,\\n) -> str:\\n    proof = response.get(\\\"proof\\\")\\n    unsigned = {key: value for key, value in response.items() if key != \\\"proof\\\"}\\n    expected_fields = {\\n        \\\"protocol_version\\\": _DISCOVERY_PROTOCOL_VERSION,\\n        \\\"nonce\\\": nonce,\\n        \\\"state_id\\\": state.get(\\\"state_id\\\"),\\n        \\\"host\\\": state.get(\\\"host\\\"),\\n        \\\"port\\\": state.get(\\\"port\\\"),\\n        \\\"pid\\\": state.get(\\\"pid\\\"),\\n        \\\"started_at\\\": state.get(\\\"started_at\\\"),\\n        \\\"guard_home\\\": state.get(\\\"guard_home\\\"),\\n        \\\"hook_event\\\": hook_event,\\n    }\\n    if any(unsigned.get(key) != value for key, value in expected_fields.items()):\\n        raise ValueError(\\\"daemon identity challenge did not match authenticated state\\\")\\n    issued_at_ms = unsigned.get(\\\"issued_at_ms\\\")\\n    expires_at_ms = unsigned.get(\\\"expires_at_ms\\\")\\n    now_ms = int(time.time() * 1000)\\n    if (\\n        not isinstance(issued_at_ms, int)\\n        or not isinstance(expires_at_ms, int)\\n        or issued_at_ms > now_ms + 1000\\n        or expires_at_ms < now_ms\\n        or expires_at_ms - issued_at_ms > _DISCOVERY_CHALLENGE_TTL_SECONDS * 1000\\n    ):\\n        raise ValueError(\\\"daemon identity challenge expired\\\")\\n    expected_proof = _sign_discovery_payload(discovery_key, unsigned)\\n    if not isinstance(proof, str) or not secrets.compare_digest(proof, expected_proof):\\n        raise ValueError(\\\"daemon identity challenge authentication failed\\\")\\n    return proof\\n\\n\\ndef _remaining_seconds(deadline: float, *, cap: float | None = None) -> float:\\n    remaining = max(0.0, deadline - time.monotonic())\\n    return remaining if cap is None else min(remaining, cap)\\n\",\"sha256\":\"f989759d4c231a8a4800e4505dce48e7eea4bdefab821817cd7260516da21876\",\"bytes\":9539},{\"path\":\"tests/test_windows_replaceable_file.py\",\"content\":\"from __future__ import annotations\\n\\nimport ctypes\\nimport os\\nfrom pathlib import Path\\nfrom types import SimpleNamespace\\n\\nimport pytest\\n\\nfrom codex_plugin_scanner.guard import windows_replaceable_file as reader\\n\\n\\nclass _WindowsOs:\\n    name = \\\"nt\\\"\\n    O_BINARY = 0x8000\\n    O_NOINHERIT = 0x80\\n\\n    def __getattr__(self, name):\\n        return getattr(os, name)\\n\\n\\nclass _Api:\\n    def __init__(self):\\n        self.handle = 41\\n        self.attributes = 0\\n        self.information_success = True\\n        self.file_type = 1\\n        self.close_success = True\\n        self.operations = []\\n\\n    def CreateFileW(self, *arguments):\\n        self.operations.append((\\\"open\\\", arguments))\\n        return self.handle\\n\\n    def GetFileInformationByHandle(self, handle, pointer):\\n        self.operations.append((\\\"information\\\", handle))\\n        information = ctypes.cast(\\n            pointer, ctypes.POINTER(reader._WindowsByHandleFileInformation),\\n        ).contents\\n        information.dwFileAttributes = self.attributes\\n        return self.information_success\\n\\n    def GetFileType(self, handle):\\n        self.operations.append((\\\"type\\\", handle))\\n        return self.file_type\\n\\n    def CloseHandle(self, handle):\\n        self.operations.append((\\\"close\\\", handle))\\n        return self.close_success\\n\\n\\n@pytest.fixture\\ndef native_open(monkeypatch):\\n    api = _Api()\\n    events = []\\n    transfers = []\\n    error = PermissionError(13, \\\"synthetic native failure\\\")\\n    setattr(error, \\\"winerror\\\", 32)\\n    monkeypatch.setattr(reader, \\\"os\\\", _WindowsOs())\\n    monkeypatch.setattr(reader, \\\"sys\\\", SimpleNamespace(audit=lambda *args: events.append(args)))\\n    monkeypatch.setattr(reader, \\\"_file_api\\\", lambda: api)\\n    monkeypatch.setattr(reader, \\\"_windows_error\\\", lambda: error)\\n    monkeypatch.setattr(reader.ctypes, \\\"set_last_error\\\", lambda code: None, raising=False)\\n\\n    def transfer(handle):\\n        transfers.append(handle)\\n        return 73\\n\\n    monkeypatch.setattr(reader, \\\"_transfer_descriptor\\\", transfer)\\n    return api, events, transfers, error\\n\\n\\ndef test_read_access_full_sharing_existing_noninheritable_open(native_open):\\n    api, events, transfers, _error = native_open\\n    target = Path(\\\"synthetic-authority\\\")\\n    descriptor = reader.open_replaceable_read_descriptor(target, os.O_RDONLY)\\n    assert descriptor == 73\\n    assert events == [(\\\"open\\\", str(target), None, os.O_RDONLY | 0x80)]\\n    assert api.operations == [\\n        (\\\"open\\\", (str(target), 0x80000000, 7, None, 3, 0x00200000, None)),\\n        (\\\"information\\\", 41), (\\\"type\\\", 41),\\n    ]\\n    assert transfers == [41]\\n\\n\\ndef test_text_callback_leaves_single_event_to_fileio(native_open):\\n    api, events, transfers, _error = native_open\\n    assert reader._text_opener(\\\"synthetic-authority\\\", 0x8080) == 73\\n    assert events == []\\n    assert transfers == [41]\\n    assert (\\\"close\\\", 41) not in api.operations\\n\\n\\n@pytest.mark.parametrize(\\n    \\\"flags\\\",\\n    [os.O_WRONLY, os.O_RDWR, os.O_CREAT, os.O_TRUNC, os.O_APPEND, 0x40, 0x4000],\\n    ids=[\\\"write\\\", \\\"read_write\\\", \\\"create\\\", \\\"truncate\\\", \\\"append\\\", \\\"delete_on_close\\\", \\\"text_mode\\\"],\\n)\\ndef test_unsafe_flags_fail_before_audit_or_open(native_open, flags):\\n    api, events, transfers, _error = native_open\\n    with pytest.raises(ValueError, match=\\\"must_be_read_only\\\"):\\n        reader.open_replaceable_read_descriptor(\\\"synthetic-authority\\\", flags)\\n    assert api.operations == events == transfers == []\\n\\n\\n@pytest.mark.parametrize(\\\"name\\\", [\\\"a\\\\0b\\\", \\\"x\\\" * 32768], ids=[\\\"nul\\\", \\\"windows_path_limit\\\"])\\ndef test_invalid_path_never_reaches_native_open(native_open, name):\\n    api, events, transfers, _error = native_open\\n    with pytest.raises(ValueError):\\n        reader.open_replaceable_read_descriptor(name, os.O_RDONLY)\\n    assert api.operations == events == transfers == []\\n\\n\\ndef test_audit_refusal_propagates_same_object_without_open(native_open, monkeypatch):\\n    api, _events, transfers, _error = native_open\\n    refusal = RuntimeError(\\\"synthetic audit refusal\\\")\\n\\n    def refuse(*_arguments):\\n        raise refusal\\n\\n    monkeypatch.setattr(reader, \\\"sys\\\", SimpleNamespace(audit=refuse))\\n    with pytest.raises(RuntimeError) as caught:\\n        reader.open_replaceable_read_descriptor(\\\"synthetic-authority\\\", os.O_RDONLY)\\n    assert caught.value is refusal\\n    assert api.operations == transfers == []\\n\\n\\n@pytest.mark.parametrize(\\\"handle\\\", [None, ctypes.c_void_p(-1).value])\\ndef test_original_open_error_is_not_wrapped_or_closed(native_open, handle):\\n    api, _events, transfers, error = native_open\\n    api.handle = handle\\n    with pytest.raises(PermissionError) as caught:\\n        reader.open_replaceable_read_descriptor(\\\"synthetic-authority\\\", os.O_RDONLY)\\n    assert caught.value is error\\n    assert getattr(error, \\\"winerror\\\") == 32\\n    assert len(api.operations) == 1\\n    assert transfers == []\\n\\n\\ndef test_information_error_is_preserved_and_owned_handle_closed(native_open):\\n    api, _events, transfers, error = native_open\\n    api.information_success = False\\n    with pytest.raises(PermissionError) as caught:\\n        reader.open_replaceable_read_descriptor(\\\"synthetic-authority\\\", os.O_RDONLY)\\n    assert caught.value is error\\n    assert api.operations[-1] == (\\\"close\\\", 41)\\n    assert transfers == []\\n\\n\\n@pytest.mark.parametrize(\\\"attributes\\\", [0x10, 0x400, 0x410], ids=[\\\"directory\\\", \\\"reparse\\\", \\\"both\\\"])\\ndef test_actual_handle_metadata_rejects_nonregular(native_open, attributes):\\n    api, _events, transfers, _error = native_open\\n    api.attributes = attributes\\n    with pytest.raises(OSError, match=\\\"not_regular\\\"):\\n        reader.open_replaceable_read_descriptor(\\\"synthetic-authority\\\", os.O_RDONLY)\\n    assert api.operations[-1] == (\\\"close\\\", 41)\\n    assert transfers == []\\n\\n\\n@pytest.mark.parametrize(\\\"file_type\\\", [2, 3], ids=[\\\"character\\\", \\\"pipe\\\"])\\ndef test_nondisk_handle_is_not_transferred(native_open, file_type):\\n    api, _events, transfers, _error = native_open\\n    api.file_type = file_type\\n    with pytest.raises(OSError, match=\\\"not_disk\\\"):\\n        reader.open_replaceable_read_descriptor(\\\"synthetic-authority\\\", os.O_RDONLY)\\n    assert api.operations[-1] == (\\\"close\\\", 41)\\n    assert transfers == []\\n\\n\\ndef test_file_type_error_retains_actual_error_and_clears_stale_code(native_open, monkeypatch):\\n    api, _events, transfers, error = native_open\\n    cleared = []\\n    monkeypatch.setattr(reader.ctypes, \\\"set_last_error\\\", cleared.append)\\n    api.file_type = 0\\n    with pytest.raises(PermissionError) as caught:\\n        reader.open_replaceable_read_descriptor(\\\"synthetic-authority\\\", os.O_RDONLY)\\n    assert cleared == [0]\\n    assert caught.value is error\\n    assert api.operations[-1] == (\\\"close\\\", 41)\\n    assert transfers == []\\n\\n\\ndef test_unknown_file_type_without_os_error_remains_rejected(native_open):\\n    api, _events, transfers, error = native_open\\n    api.file_type = 0\\n    setattr(error, \\\"winerror\\\", 0)\\n    with pytest.raises(OSError, match=\\\"not_disk\\\"):\\n        reader.open_replaceable_read_descriptor(\\\"synthetic-authority\\\", os.O_RDONLY)\\n    assert api.operations[-1] == (\\\"close\\\", 41)\\n    assert transfers == []\\n\\n\\ndef test_descriptor_transfer_failure_keeps_original_error_and_closes(native_open, monkeypatch):\\n    api, _events, _transfers, _error = native_open\\n    failure = OSError(\\\"synthetic transfer failure\\\")\\n\\n    def transfer(_handle):\\n        raise failure\\n\\n    monkeypatch.setattr(reader, \\\"_transfer_descriptor\\\", transfer)\\n    with pytest.raises(OSError) as caught:\\n        reader.open_replaceable_read_descriptor(\\\"synthetic-authority\\\", os.O_RDONLY)\\n    assert caught.value is failure\\n    assert api.operations.count((\\\"close\\\", 41)) == 1\\n\\n\\ndef test_secondary_close_failure_does_not_replace_original_error(native_open):\\n    api, _events, transfers, error = native_open\\n    api.information_success = False\\n    api.close_success = False\\n    with pytest.raises(PermissionError) as caught:\\n        reader.open_replaceable_read_descriptor(\\\"synthetic-authority\\\", os.O_RDONLY)\\n    assert caught.value is error\\n    assert error.__notes__ == [\\\"windows_replaceable_read_close_failed\\\"]\\n    assert api.operations.count((\\\"close\\\", 41)) == 1\\n    assert transfers == []\\n\\n\\ndef test_text_wrapper_preserves_utf8_newlines_and_closes(tmp_path, monkeypatch):\\n    target = tmp_path / \\\"synthetic-authority\\\"\\n    target.write_bytes(\\\"first\\\\r\\\\nsecond\\\\né\\\".encode(\\\"utf-8\\\"))\\n    descriptors = []\\n\\n    def opener(path, flags):\\n        descriptor = os.open(path, flags)\\n        descriptors.append(descriptor)\\n        return descriptor\\n\\n    monkeypatch.setattr(reader, \\\"_text_opener\\\", opener)\\n    assert reader.read_replaceable_text(target) == \\\"first\\\\nsecond\\\\né\\\"\\n    assert len(descriptors) == 1\\n    with pytest.raises(OSError):\\n        os.fstat(descriptors[0])\\n\\n\\ndef test_text_decode_failure_still_closes_descriptor(tmp_path, monkeypatch):\\n    target = tmp_path / \\\"synthetic-authority\\\"\\n    target.write_bytes(b\\\"\\\\xff\\\")\\n    descriptors = []\\n\\n    def opener(path, flags):\\n        descriptor = os.open(path, flags)\\n        descriptors.append(descriptor)\\n        return descriptor\\n\\n    monkeypatch.setattr(reader, \\\"_text_opener\\\", opener)\\n    with pytest.raises(UnicodeDecodeError):\\n        reader.read_replaceable_text(target)\\n    assert len(descriptors) == 1\\n    with pytest.raises(OSError):\\n        os.fstat(descriptors[0])\\n\",\"sha256\":\"6f77b3ed8bc683ce52f9f950ea6266da10d1aeac6d45d4316ae20b03adcfdf04\",\"bytes\":9171},{\"path\":\"tests/test_private_reader_descriptor_guards.py\",\"content\":\"from __future__ import annotations\\n\\nimport os\\nimport stat\\nfrom pathlib import Path\\nfrom types import SimpleNamespace\\n\\nimport pytest\\n\\nfrom codex_plugin_scanner.guard import private_file_io as reader\\n\\n\\nclass _DescriptorObserver:\\n    def __init__(self, *, change_before=None, change_after=None):\\n        self.change_before = change_before or {}\\n        self.change_after = change_after or {}\\n        self.fstat_calls = 0\\n        self.read_calls = 0\\n        self.closed = []\\n\\n    def __getattr__(self, name):\\n        return getattr(os, name)\\n\\n    def fstat(self, descriptor):\\n        self.fstat_calls += 1\\n        metadata = os.fstat(descriptor)\\n        values = {\\n            name: getattr(metadata, name)\\n            for name in (\\\"st_dev\\\", \\\"st_ino\\\", \\\"st_mode\\\", \\\"st_uid\\\", \\\"st_size\\\", \\\"st_mtime_ns\\\", \\\"st_ctime_ns\\\")\\n        }\\n        changes = self.change_before if self.fstat_calls == 1 else self.change_after\\n        for name, value in changes.items():\\n            values[name] = value(values[name]) if callable(value) else value\\n        return SimpleNamespace(**values)\\n\\n    def read(self, descriptor, maximum):\\n        self.read_calls += 1\\n        return os.read(descriptor, maximum)\\n\\n    def close(self, descriptor):\\n        os.close(descriptor)\\n        self.closed.append(descriptor)\\n\\n\\ndef _authority(tmp_path: Path) -> Path:\\n    parent = tmp_path / \\\"private\\\"\\n    parent.mkdir(mode=0o700)\\n    path = parent / \\\"authority\\\"\\n    path.write_bytes(b\\\"synthetic\\\\n\\\")\\n    if os.name != \\\"nt\\\":\\n        path.chmod(0o600)\\n    return path\\n\\n\\n@pytest.mark.parametrize(\\n    \\\"change\\\",\\n    [{\\\"st_ino\\\": lambda value: value + 1}, {\\\"st_mode\\\": stat.S_IFDIR | 0o700}, {\\\"st_size\\\": 4097}],\\n    ids=[\\\"different_handle_identity\\\", \\\"directory_handle\\\", \\\"oversized_handle\\\"],\\n)\\ndef test_opened_descriptor_guards_reject_before_read_and_close(tmp_path, monkeypatch, change):\\n    target = _authority(tmp_path)\\n    observer = _DescriptorObserver(change_before=change)\\n    monkeypatch.setattr(reader, \\\"os\\\", observer)\\n    assert reader.read_private_regular_bytes(target, max_bytes=4096, require_private_parent=True) is None\\n    assert observer.fstat_calls == 1\\n    assert observer.read_calls == 0\\n    assert len(observer.closed) == 1\\n    with pytest.raises(OSError):\\n        os.fstat(observer.closed[0])\\n\\n\\n@pytest.mark.skipif(os.name == \\\"nt\\\", reason=\\\"Original explicit owner check is POSIX-only\\\")\\ndef test_opened_descriptor_owner_must_still_match(tmp_path, monkeypatch):\\n    target = _authority(tmp_path)\\n    observer = _DescriptorObserver(change_before={\\\"st_uid\\\": lambda value: value + 1})\\n    monkeypatch.setattr(reader, \\\"os\\\", observer)\\n    assert reader.read_private_regular_bytes(target, max_bytes=4096, require_private_parent=True) is None\\n    assert observer.read_calls == 0\\n    assert len(observer.closed) == 1\\n\\n\\n@pytest.mark.parametrize(\\n    \\\"field\\\",\\n    [\\\"st_dev\\\", \\\"st_ino\\\", \\\"st_mode\\\", \\\"st_size\\\", \\\"st_mtime_ns\\\", \\\"st_ctime_ns\\\"],\\n)\\ndef test_changed_descriptor_metadata_is_never_returned(tmp_path, monkeypatch, field):\\n    target = _authority(tmp_path)\\n    observer = _DescriptorObserver(change_after={field: lambda value: value + 1})\\n    monkeypatch.setattr(reader, \\\"os\\\", observer)\\n    assert reader.read_private_regular_bytes(target, max_bytes=4096, require_private_parent=True) is None\\n    assert observer.fstat_calls == 2\\n    assert observer.read_calls > 0\\n    assert len(observer.closed) == 1\\n\\n\\ndef test_descriptor_read_exception_keeps_identity_and_closes(tmp_path, monkeypatch):\\n    target = _authority(tmp_path)\\n    observer = _DescriptorObserver()\\n    failure = OSError(\\\"synthetic read failure\\\")\\n\\n    def fail_read(_descriptor, _maximum):\\n        raise failure\\n\\n    monkeypatch.setattr(observer, \\\"read\\\", fail_read)\\n    monkeypatch.setattr(reader, \\\"os\\\", observer)\\n    with pytest.raises(OSError) as caught:\\n        reader.read_private_regular_bytes(target, max_bytes=4096, require_private_parent=True)\\n    assert caught.value is failure\\n    assert len(observer.closed) == 1\\n\\n\\ndef test_codex_token_recheck_still_rejects_authenticated_state_mismatch(tmp_path):\\n    import hashlib\\n\\n    from codex_plugin_scanner.guard.adapters import codex_daemon_hook_auth\\n    from codex_plugin_scanner.guard.daemon import manager\\n\\n    home = tmp_path / \\\"guard\\\"\\n    manager._ensure_private_directory(home)\\n    manager._write_private_atomic_text(home / \\\"daemon-auth-token\\\", \\\"synthetic-new-token\\\")\\n    state = {\\\"auth_token_id\\\": hashlib.sha256(b\\\"synthetic-old-token\\\").hexdigest()}\\n    with pytest.raises(ValueError, match=\\\"does not match authenticated state\\\"):\\n        codex_daemon_hook_auth._daemon_auth_token(home / \\\"daemon-state.json\\\", state)\\n\",\"sha256\":\"182650180dd3dd4cf3450de915e52d7013e9a3894bdb2708e850634fa78a5ef7\",\"bytes\":4597},{\"path\":\"ci/native_runtime/windows_replaceable_reader_child.py\",\"content\":\"\\\"\\\"\\\"Bounded child for source-only Windows reader regression controls.\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nimport argparse\\nimport errno\\nimport json\\nimport os\\nimport sys\\nfrom pathlib import Path\\n\\n_OLD = \\\"synthetic-before-token\\\"\\n_NEW = \\\"synthetic-after-token\\\"\\n\\n\\ndef _code(error: BaseException | None) -> dict[str, object] | None:\\n    if error is None:\\n        return None\\n    kind = \\\"other\\\"\\n    if type(error) is PermissionError:\\n        kind = \\\"PermissionError\\\"\\n    elif isinstance(error, OSError):\\n        kind = \\\"OSError\\\"\\n    return {\\\"kind\\\": kind, \\\"errno\\\": getattr(error, \\\"errno\\\", None), \\\"winerror\\\": getattr(error, \\\"winerror\\\", None)}\\n\\n\\nclass _WriterOs:\\n    def __init__(self, original, target: Path, hold_source: bool):\\n        self.original = original\\n        self.target = target\\n        self.hold_source = hold_source\\n        self.closed = []\\n        self.replace_calls = 0\\n        self.writer_fd_closed = False\\n        self.source_reader_opened = False\\n        self.source_reader_closed = False\\n        self.replace_returned = False\\n        self.error: BaseException | None = None\\n\\n    def __getattr__(self, name):\\n        return getattr(self.original, name)\\n\\n    def close(self, descriptor):\\n        self.original.close(descriptor)\\n        self.closed.append(descriptor)\\n\\n    def replace(self, source, destination):\\n        self.replace_calls += 1\\n        if self.replace_calls != 1 or Path(destination) != self.target or not self.closed:\\n            raise RuntimeError(\\\"control_writer_boundary_invalid\\\")\\n        try:\\n            self.original.fstat(self.closed[-1])\\n        except OSError as error:\\n            self.writer_fd_closed = error.errno == errno.EBADF\\n        if not self.writer_fd_closed:\\n            raise RuntimeError(\\\"control_writer_descriptor_still_open\\\")\\n        descriptor = None\\n        try:\\n            if self.hold_source:\\n                # An intentionally noncooperating CRT source handle is a separate\\n                # negative control. No source reader is opened by the product fix.\\n                descriptor = self.original.open(source, self.original.O_RDONLY)\\n                self.source_reader_opened = True\\n            try:\\n                self.original.replace(source, destination)\\n            except BaseException as error:\\n                self.error = error\\n                raise\\n            self.replace_returned = True\\n        finally:\\n            if descriptor is not None:\\n                self.original.close(descriptor)\\n                self.source_reader_closed = True\\n\\n\\ndef _writer(args) -> int:\\n    from codex_plugin_scanner.guard.daemon import manager, manager_pending_launch\\n\\n    original = manager.os\\n    observer = _WriterOs(original, args.target, args.hold_crt_source)\\n    failure = None\\n    locked = False\\n    writer_calls = 0\\n    if manager._write_private_atomic_text is not manager_pending_launch._write_private_atomic_text:\\n        raise RuntimeError(\\\"control_writer_alias_mismatch\\\")\\n    setattr(manager, \\\"os\\\", observer)\\n    try:\\n        with manager._guard_daemon_state_write_lock(args.target.parent):\\n            locked = True\\n            writer_calls += 1\\n            manager._write_private_atomic_text(args.target, _NEW)\\n    except BaseException as error:\\n        failure = error\\n    finally:\\n        setattr(manager, \\\"os\\\", original)\\n    report = {\\n        \\\"schema\\\": 1, \\\"operation\\\": \\\"writer\\\", \\\"writer_calls\\\": writer_calls,\\n        \\\"writer_locked\\\": locked, \\\"replace_calls\\\": observer.replace_calls,\\n        \\\"writer_fd_closed_before_replace\\\": observer.writer_fd_closed,\\n        \\\"source_reader_opened\\\": observer.source_reader_opened,\\n        \\\"source_reader_closed\\\": observer.source_reader_closed,\\n        \\\"replace_returned\\\": observer.replace_returned,\\n        \\\"original_exception_identity_preserved\\\": failure is None or failure is observer.error,\\n        \\\"error\\\": _code(failure),\\n        \\\"temporary_siblings_removed\\\": not list(args.target.parent.glob(\\\".daemon-auth-token.*\\\")),\\n    }\\n    print(json.dumps(report, sort_keys=True), flush=True)\\n    return 0 if failure is None else 1\\n\\n\\ndef _audit(args) -> int:\\n    from codex_plugin_scanner.guard import windows_replaceable_file as reader\\n\\n    target = args.target\\n    events = []\\n    refusal = RuntimeError(\\\"synthetic audit refusal\\\")\\n    observed = None\\n    payload = None\\n\\n    def hook(event, arguments):\\n        if (\\n            event == \\\"open\\\" and isinstance(arguments[0], (str, os.PathLike))\\n            and os.fspath(arguments[0]) == str(target)\\n        ):\\n            events.append({\\\"mode\\\": arguments[1], \\\"flags\\\": arguments[2]})\\n            if args.refuse:\\n                raise refusal\\n\\n    sys.addaudithook(hook)\\n    try:\\n        if args.route == \\\"bounded\\\":\\n            flags = os.O_RDONLY | getattr(os, \\\"O_CLOEXEC\\\", 0) | getattr(os, \\\"O_NOFOLLOW\\\", 0)\\n            opener = reader.open_replaceable_read_descriptor if args.candidate else os.open\\n            descriptor = opener(target, flags)\\n            try:\\n                payload = os.read(descriptor, 4096)\\n            finally:\\n                os.close(descriptor)\\n        elif args.candidate:\\n            payload = reader.read_replaceable_text(target)\\n        else:\\n            payload = target.read_text(encoding=\\\"utf-8\\\")\\n    except BaseException as error:\\n        observed = error\\n    expected = b\\\"synthetic\\\\r\\\\nvalue\\\\x1a\\\\n\\\" if args.route == \\\"bounded\\\" else \\\"synthetic\\\\nvalue\\\\x1a\\\\n\\\"\\n    print(json.dumps({\\n        \\\"schema\\\": 1, \\\"operation\\\": \\\"audit\\\", \\\"events\\\": events,\\n        \\\"refusal_same_object\\\": observed is refusal,\\n        \\\"result_matches\\\": payload == expected, \\\"error\\\": _code(observed),\\n    }, sort_keys=True), flush=True)\\n    return 0\\n\\n\\ndef main() -> int:\\n    parser = argparse.ArgumentParser(description=__doc__)\\n    parser.add_argument(\\\"--source-root\\\", type=Path, required=True)\\n    parser.add_argument(\\\"--target\\\", type=Path, required=True)\\n    parser.add_argument(\\\"--operation\\\", choices=(\\\"writer\\\", \\\"audit\\\"), required=True)\\n    parser.add_argument(\\\"--hold-crt-source\\\", action=\\\"store_true\\\")\\n    parser.add_argument(\\\"--route\\\", choices=(\\\"bounded\\\", \\\"text\\\"), default=\\\"bounded\\\")\\n    parser.add_argument(\\\"--candidate\\\", action=\\\"store_true\\\")\\n    parser.add_argument(\\\"--refuse\\\", action=\\\"store_true\\\")\\n    args = parser.parse_args()\\n    if os.name != \\\"nt\\\" or sys.flags.isolated != 1:\\n        raise RuntimeError(\\\"control_requires_isolated_windows_python\\\")\\n    source = args.source_root.resolve(strict=True)\\n    sys.path.insert(0, str(source / \\\"src\\\"))\\n    if args.operation == \\\"writer\\\":\\n        return _writer(args)\\n    return _audit(args)\\n\\n\\nif __name__ == \\\"__main__\\\":\\n    raise SystemExit(main())\\n\",\"sha256\":\"d2c668f1e895e71613a4b7b5082bf27036ec5fb8e20b919a299e589b9fd8f984\",\"bytes\":6558},{\"path\":\"tests/test_windows_replaceable_reader_process.py\",\"content\":\"from __future__ import annotations\\n\\nimport builtins\\nimport json\\nimport os\\nimport queue\\nimport subprocess\\nimport sys\\nimport threading\\nfrom pathlib import Path\\n\\nimport pytest\\n\\nfrom codex_plugin_scanner.guard import private_file_io\\nfrom codex_plugin_scanner.guard import windows_replaceable_file as replaceable\\nfrom codex_plugin_scanner.guard.adapters import codex_daemon_hook_auth\\nfrom codex_plugin_scanner.guard.daemon import manager\\n\\npytestmark = pytest.mark.skipif(os.name != \\\"nt\\\", reason=\\\"Real Windows sharing and audit semantics\\\")\\n_CONTROL_SECONDS = 5.0\\n_ROOT = Path(__file__).resolve().parents[1]\\n_CHILD = _ROOT / \\\"ci/native_runtime/windows_replaceable_reader_child.py\\\"\\n_OLD = \\\"synthetic-before-token\\\"\\n_NEW = \\\"synthetic-after-token\\\"\\n\\n\\ndef _run_child(target: Path, *arguments: str):\\n    command = [\\n        sys.executable, \\\"-I\\\", str(_CHILD), \\\"--source-root\\\", str(_ROOT),\\n        \\\"--target\\\", str(target), *arguments,\\n    ]\\n    process = subprocess.Popen(\\n        command, stdin=subprocess.DEVNULL, stdout=subprocess.PIPE,\\n        stderr=subprocess.PIPE, close_fds=True,\\n    )\\n    failure = None\\n    stdout = stderr = b\\\"\\\"\\n    try:\\n        stdout, stderr = process.communicate(timeout=_CONTROL_SECONDS)\\n    except BaseException as error:\\n        failure = error\\n    finally:\\n        if process.poll() is None:\\n            try:\\n                process.kill()\\n                process.communicate(timeout=_CONTROL_SECONDS)\\n            except BaseException as cleanup_error:\\n                if failure is None:\\n                    failure = cleanup_error\\n                else:\\n                    failure.add_note(\\\"control_child_cleanup_failed\\\")\\n    if failure is not None:\\n        raise failure\\n    if len(stdout) > 8192 or stderr:\\n        raise RuntimeError(\\\"control_child_output_invalid\\\")\\n    return process.returncode, json.loads(stdout)\\n\\n\\nclass _HeldRead:\\n    def __init__(self):\\n        self.entered = threading.Event()\\n        self.release = threading.Event()\\n        self.closed = threading.Event()\\n        self.owner: int | None = None\\n        self.descriptor: int | None = None\\n        self.inheritable: bool | None = None\\n        self.identity: tuple[int, int] | None = None\\n\\n    def pause(self, descriptor):\\n        if threading.get_ident() != self.owner or self.descriptor is not None:\\n            return\\n        self.descriptor = descriptor\\n        self.inheritable = os.get_inheritable(descriptor)\\n        metadata = os.fstat(descriptor)\\n        self.identity = metadata.st_dev, metadata.st_ino\\n        self.entered.set()\\n        if not self.release.wait(_CONTROL_SECONDS):\\n            raise TimeoutError(\\\"control_reader_release_timeout\\\")\\n\\n\\nclass _ReaderOs:\\n    def __init__(self, held):\\n        self.held = held\\n\\n    def __getattr__(self, name):\\n        return getattr(os, name)\\n\\n    def read(self, descriptor, maximum):\\n        self.held.pause(descriptor)\\n        return os.read(descriptor, maximum)\\n\\n    def close(self, descriptor):\\n        os.close(descriptor)\\n        if descriptor == self.held.descriptor and threading.get_ident() == self.held.owner:\\n            self.held.closed.set()\\n\\n\\nclass _TextRead:\\n    def __init__(self, handle, held):\\n        self.handle = handle\\n        self.held = held\\n\\n    def __enter__(self):\\n        self.handle.__enter__()\\n        return self\\n\\n    def read(self):\\n        self.held.pause(self.handle.fileno())\\n        return self.handle.read()\\n\\n    def __exit__(self, *arguments):\\n        try:\\n            return self.handle.__exit__(*arguments)\\n        finally:\\n            if self.handle.closed:\\n                self.held.closed.set()\\n\\n\\n@pytest.mark.parametrize(\\\"route\\\", [\\\"bounded_manager\\\", \\\"codex_text\\\"])\\n@pytest.mark.parametrize(\\\"hold_crt_source\\\", [False, True], ids=[\\\"destination_only\\\", \\\"separate_crt_source\\\"])\\ndef test_actual_reader_allows_other_process_replace_without_changing_writer(\\n    tmp_path, monkeypatch, record_property, route, hold_crt_source,\\n):\\n    assert Path(private_file_io.__file__).resolve() == _ROOT / \\\"src/codex_plugin_scanner/guard/private_file_io.py\\\"\\n    assert Path(replaceable.__file__).resolve() == _ROOT / \\\"src/codex_plugin_scanner/guard/windows_replaceable_file.py\\\"\\n    home = tmp_path / \\\"guard\\\"\\n    manager._ensure_private_directory(home)\\n    target = home / \\\"daemon-auth-token\\\"\\n    manager._write_private_atomic_text(target, _OLD)\\n    before = target.stat()\\n    old_identity = before.st_dev, before.st_ino\\n    held = _HeldRead()\\n    values = queue.Queue(maxsize=1)\\n    errors = queue.Queue(maxsize=1)\\n\\n    def read():\\n        held.owner = threading.get_ident()\\n        try:\\n            if route == \\\"bounded_manager\\\":\\n                value = manager.load_guard_daemon_auth_token(home)\\n            else:\\n                value = codex_daemon_hook_auth._private_file_text(target, label=\\\"token\\\")\\n            values.put_nowait(value)\\n        except BaseException as error:\\n            errors.put_nowait(error)\\n\\n    def open_text(path, *arguments, **keywords):\\n        handle = builtins.open(path, *arguments, **keywords)\\n        if Path(path) == target and threading.get_ident() == held.owner:\\n            return _TextRead(handle, held)\\n        return handle\\n\\n    thread = threading.Thread(target=read, name=\\\"owned-source-reader\\\", daemon=True)\\n    report = None\\n    code = None\\n    held_after_child = False\\n    old_handle_after_child = False\\n    with monkeypatch.context() as patch:\\n        patch.setattr(private_file_io, \\\"os\\\", _ReaderOs(held))\\n        patch.setattr(replaceable, \\\"open\\\", open_text, raising=False)\\n        thread.start()\\n        try:\\n            if not held.entered.wait(_CONTROL_SECONDS):\\n                raise TimeoutError(\\\"control_reader_ready_timeout\\\")\\n            if held.descriptor is None:\\n                raise RuntimeError(\\\"control_reader_descriptor_missing\\\")\\n            extra = [\\\"--hold-crt-source\\\"] if hold_crt_source else []\\n            code, report = _run_child(target, \\\"--operation\\\", \\\"writer\\\", *extra)\\n            held_after_child = thread.is_alive() and not held.closed.is_set()\\n            after = os.fstat(held.descriptor)\\n            old_handle_after_child = (after.st_dev, after.st_ino) == old_identity\\n        finally:\\n            held.release.set()\\n            thread.join(_CONTROL_SECONDS)\\n            record_property(\\\"reader_retired\\\", not thread.is_alive())\\n            record_property(\\\"reader_descriptor_closed\\\", held.closed.is_set())\\n            record_property(\\\"writer_is_separate_process\\\", True)\\n            record_property(\\\"source_crt_negative_control\\\", hold_crt_source)\\n    assert not thread.is_alive()\\n    assert errors.empty()\\n    assert held.closed.is_set()\\n    assert held.inheritable is False\\n    assert held.identity == old_identity\\n    assert held_after_child and old_handle_after_child\\n    assert values.get_nowait() == _OLD\\n    assert report is not None\\n    assert report[\\\"writer_calls\\\"] == report[\\\"replace_calls\\\"] == 1\\n    assert report[\\\"writer_locked\\\"] and report[\\\"writer_fd_closed_before_replace\\\"]\\n    assert report[\\\"source_reader_opened\\\"] is hold_crt_source\\n    assert report[\\\"source_reader_closed\\\"] is hold_crt_source\\n    assert report[\\\"temporary_siblings_removed\\\"]\\n    assert report[\\\"original_exception_identity_preserved\\\"]\\n    if hold_crt_source:\\n        assert code == 1\\n        assert report[\\\"replace_returned\\\"] is False\\n        assert report[\\\"error\\\"] == {\\\"kind\\\": \\\"PermissionError\\\", \\\"errno\\\": 13, \\\"winerror\\\": 32}\\n        assert target.read_text(encoding=\\\"utf-8\\\") == _OLD\\n    else:\\n        assert code == 0\\n        assert report[\\\"replace_returned\\\"] is True\\n        assert report[\\\"error\\\"] is None\\n        assert target.read_text(encoding=\\\"utf-8\\\") == _NEW\\n        current = target.stat()\\n        assert (current.st_dev, current.st_ino) != old_identity\\n    assert not list(home.glob(\\\".daemon-auth-token.*\\\"))\\n\\n\\n@pytest.mark.parametrize(\\\"route\\\", [\\\"bounded\\\", \\\"text\\\"])\\n@pytest.mark.parametrize(\\\"refuse\\\", [False, True], ids=[\\\"observe\\\", \\\"refuse\\\"])\\ndef test_real_python_audit_matches_original_once(tmp_path, route, refuse):\\n    target = tmp_path / \\\"authority\\\"\\n    target.write_bytes(b\\\"synthetic\\\\r\\\\nvalue\\\\x1a\\\\n\\\")\\n    extra = [\\\"--refuse\\\"] if refuse else []\\n    original_code, original = _run_child(target, \\\"--operation\\\", \\\"audit\\\", \\\"--route\\\", route, *extra)\\n    candidate_code, candidate = _run_child(\\n        target, \\\"--operation\\\", \\\"audit\\\", \\\"--route\\\", route, \\\"--candidate\\\", *extra,\\n    )\\n    assert original_code == candidate_code == 0\\n    assert candidate == original\\n    assert len(candidate[\\\"events\\\"]) == 1\\n    assert candidate[\\\"refusal_same_object\\\"] is refuse\\n    assert candidate[\\\"result_matches\\\"] is (not refuse)\\n\",\"sha256\":\"b819964e219fe58491ca69843eac10cbc8832bb131d932d565cffdfbd687dbff\",\"bytes\":8546}]")
